export default function getCanvasEllipseCorners(ellipseCanvasPoints) {
    const xs = ellipseCanvasPoints.map((point) => point[0]);
    const ys = ellipseCanvasPoints.map((point) => point[1]);
    const topLeft = [Math.min(...xs), Math.min(...ys)];
    const bottomRight = [Math.max(...xs), Math.max(...ys)];
    return [topLeft, bottomRight];
}
